const cases=['stream','complete','streamSimple','completeSimple','streamDeferred','fetchDeferred','cancelDeferred','wrong-type-stream','missing-auth-stream','setup-plain-throw'],rows=[],raw=[];
const originalRowsPush=rows.push;rows.push=function(...args){clockSlices.push(clockCalls.slice(clockOffset));clockOffset=clockCalls.length;return Reflect.apply(originalRowsPush,this,args)};
for(const name of cases){const events=[],signal=new AbortController().signal,model={id:'chat',name:'Chat',provider:'fixture',api:'fixture-chat',baseUrl:'https://original.invalid',input:['text'],contextWindow:1000,cost:{input:0,output:0,cacheRead:0,cacheWrite:0}},context={systemPrompt:'System',messages:[{role:'user',content:'Hi',timestamp:0}],tools:[{name:'fixture-tool',description:'Local fixture',parameters:{type:'object',properties:{}}}]},models=A.createModels({authContext:{env:async()=>undefined,fileExists:async()=>false}}),message={role:'assistant',content:[{type:'text',text:'done'}],api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:'stop',timestamp:0};
const dispatch=(method,selected,input,options)=>{events.push({type:method,model:selected,input,options:{...options,signal:undefined},keys:Object.keys(options),signalSame:options.signal===signal});if(name==='setup-plain-throw')throw{message:'not-an-Error'};const stream=new A.AssistantMessageEventStream();queueMicrotask(()=>{stream.push({type:'start',partial:message});stream.push({type:'done',reason:'stop',message});stream.end(message)});return stream};
models.setProvider(A.createProvider({id:'fixture',models:[model],auth:{apiKey:{name:'Fixture',resolve:async()=>{events.push({type:'auth'});return name==='missing-auth-stream'?undefined:{auth:{apiKey:'fixture-key',baseUrl:'https://resolved.invalid',headers:{AUTH:'provider'}},source:'fixture'}}}},api:{stream:(...args)=>dispatch('stream',...args),streamSimple:(...args)=>dispatch('streamSimple',...args),fetchDeferred:(...args)=>dispatch('fetchDeferred',...args),cancelDeferred:async(selected,handle,options)=>{events.push({type:'cancelDeferred',model:selected,handle,options:{...options,signal:undefined},keys:Object.keys(options),signalSame:options.signal===signal})}}}));
const selected=name==='wrong-type-stream'?{...model,type:'classifier'}:model,options={signal,headers:{auth:'request'}},handle={id:'fixture-deferred'};let value,stream,received=[],brand;const start=Date.now();
if(name==='complete')value=await models.complete(selected,context,options);else if(name==='completeSimple')value=await models.completeSimple(selected,context,options);else if(name==='fetchDeferred')value=await models.fetchDeferred(selected,handle,options);else if(name==='cancelDeferred')value=await models.cancelDeferred(selected,handle,options);else{stream=name==='streamSimple'?models.streamSimple(selected,context,options):name==='streamDeferred'?models.streamDeferred(selected,handle,options):models.stream(selected,context,options);brand=stream instanceof A.AssistantMessageEventStream;events.push({type:'returned-stream'});for await(const event of stream)received.push(event);value=await stream.result()}
