Date.now=originalDateNow;rows.push=originalRowsPush;
for(let i=0;i<rows.length;i++){const row=rows[i],calls=clockSlices[i];if(calls[0]!==row.start||calls.at(-1)!==row.end||row.name!=='cancelDeferred'&&calls.length<4)throw Error(JSON.stringify({clockCount:row.name,calls,row}));const phase=row.name==='cancelDeferred'?{}:{lazyStartedAt:calls[1],outerStartedAt:calls[2]};row.clockPhase=phase;raw[i].clockPhase=phase;if(row.value?.stopReason==='error'){const expectedPresence=row.value.timestamp>=phase.outerStartedAt;if(row.value.timestamp!==phase.lazyStartedAt||Object.hasOwn(row.value,'durationMs')!==expectedPresence||row.received[0].error!==row.value)throw Error('Source timing guard mismatch')}}if(clockOffset!==clockCalls.length)throw Error('unexpected original clock call');
